def build(p):
    import cadquery as cq
    n = int(round(p['n_zones'])); x, z = p['R_station'] - p['e_head'], 0
    edges = [p['r_wafer'] * math.sqrt(k / n) for k in range(n + 1)]   # equal-area zones (assumption)
    solids = []
    for k in range(n):
        ri, ro = edges[k] + (p['gap'] / 2 if k else 0), edges[k + 1] - p['gap'] / 2
        w = cq.Workplane("XZ").circle(ro)
        if ri > 0:
            w = w.circle(ri)
        solids.append(w.extrude(-p['t']).translate((x, p['y'] + p['t'], z)).val())
    return cq.Workplane().add(cq.Compound.makeCompound(solids))
